INSERT INTO curriculum_nodes (id, slug, phase_id, order_index, title, subtitle, cs_foundation, ai_convergence, xp_reward, level_required, position_x, position_y, handbook_markdown, starter_code, test_suite, defense_prompts) VALUES
('node-7-31', 'phase-07-lesson-31-terraform-modules-workspaces-production-a', 'module-10', 31, 'Lesson 10.31: Terraform Modules, Workspaces & Production Architecture', 'Prerequisites: Lesson 7.30', 'Prerequisites: Lesson 7.30 | Subtopics: 6 items', 'Systems project application', 240, 8, 1810.0, 1550.0, '# Lesson 7.31: Terraform Modules, Workspaces & Production Architecture

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 7.30
- **Subtopics**:
  - `7.31.1` Terraform module architecture: root modules, child modules, input variables, outputs, and validation blocks
  - `7.31.2` Module design best practices: single responsibility, version pinning, and publishing to private registries
  - `7.31.3` Environment segregation: Terraform Workspaces vs directory-based layout (separate root modules per environment)
  - `7.31.4` Why directory-based segregation (`environments/prod`, `environments/stage`) is superior to workspaces for blast radius control
  - `7.31.5` Terraform expressions: for_each, count, dynamic blocks, splat operators, and conditional expressions
  - `7.31.6` Static analysis and policy-as-code: `tflint`, `tfsec`, and Open Policy Agent (OPA) / Conftest compliance validation in CI
- **Key Failure Modes & Edge Cases**: Using `count` instead of `for_each` causing massive cascading resource destructions when reordering list elements.
- **Verification & Mastery Check**: Build a reusable, versioned Terraform module for multi-zone GKE clusters with strict input variable validations.
- **Project Application**: InfraBlueprint: Production Terraform module library.', '{"solution.py": "# Phase 7 // Lesson 7.31: Terraform Modules, Workspaces & Production Architecture\n\ndef solve():\n    \"\"\"\n    Verification: Build a reusable, versioned Terraform module for multi-zone GKE clusters with strict input variable \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.31", "subtopics_count": 6, "verification_criteria": "Build a reusable, versioned Terraform module for multi-zone GKE clusters with strict input variable validations.", "subtopics": ["7.31.1 Terraform module architecture: root modules, child modules, input variables, outputs, and validation blocks", "7.31.2 Module design best practices: single responsibility, version pinning, and publishing to private registries", "7.31.3 Environment segregation: Terraform Workspaces vs directory-based layout (separate root modules per environment)", "7.31.4 Why directory-based segregation (`environments/prod`, `environments/stage`) is superior to workspaces for blast radius control", "7.31.5 Terraform expressions: for_each, count, dynamic blocks, splat operators, and conditional expressions", "7.31.6 Static analysis and policy-as-code: `tflint`, `tfsec`, and Open Policy Agent (OPA) / Conftest compliance validation in CI"]}'::jsonb, '["Explain how this implementation prevents: Using `count` instead of `for_each` causing massive cascading resource destructions when reordering list elements.", "How does Terraform Modules, Workspaces & Production Architecture scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-32', 'phase-07-lesson-32-terraform-drift-detection-refactoring-ter', 'module-10', 32, 'Lesson 10.32: Terraform Drift Detection, Refactoring & Terragrunt', 'Prerequisites: Lesson 7.31', 'Prerequisites: Lesson 7.31 | Subtopics: 6 items', 'Systems project application', 240, 8, 1870.0, 1600.0, '# Lesson 7.32: Terraform Drift Detection, Refactoring & Terragrunt

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 7.31
- **Subtopics**:
  - `7.32.1` Infrastructure drift: out-of-band manual console edits, silent cloud provider API changes, and reconciling state
  - `7.32.2` Automated drift detection: running scheduled `terraform plan -detailed-exitcode` pipelines in CI/CD
  - `7.32.3` Refactoring Terraform configurations: `moved` blocks for seamless resource renaming without destroying live infrastructure
  - `7.32.4` Targeted operations: `-target` flag usage, emergency manual state surgery (`state rm`, `state import`), and risks
  - `7.32.5` DRY Terraform with Terragrunt: centralized backend generation, common provider inheritance, and dependency graphs
  - `7.32.6` Handling breaking provider upgrades: managing provider lock files (`.terraform.lock.hcl`) across teams
- **Key Failure Modes & Edge Cases**: Manual console modifications creating unresolvable drift; dangerous `-target` applications leaving state partially updated.
- **Verification & Mastery Check**: Refactor an existing monolithic Terraform configuration using `moved` blocks to relocate resources into modules with zero recreations.
- **Project Application**: InfraBlueprint: Drift detection automation and Terragrunt orchestrations.', '{"solution.py": "# Phase 7 // Lesson 7.32: Terraform Drift Detection, Refactoring & Terragrunt\n\ndef solve():\n    \"\"\"\n    Verification: Refactor an existing monolithic Terraform configuration using `moved` blocks to relocate resources i\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.32", "subtopics_count": 6, "verification_criteria": "Refactor an existing monolithic Terraform configuration using `moved` blocks to relocate resources into modules with zero recreations.", "subtopics": ["7.32.1 Infrastructure drift: out-of-band manual console edits, silent cloud provider API changes, and reconciling state", "7.32.2 Automated drift detection: running scheduled `terraform plan -detailed-exitcode` pipelines in CI/CD", "7.32.3 Refactoring Terraform configurations: `moved` blocks for seamless resource renaming without destroying live infrastructure", "7.32.4 Targeted operations: `-target` flag usage, emergency manual state surgery (`state rm`, `state import`), and risks", "7.32.5 DRY Terraform with Terragrunt: centralized backend generation, common provider inheritance, and dependency graphs", "7.32.6 Handling breaking provider upgrades: managing provider lock files (`.terraform.lock.hcl`) across teams"]}'::jsonb, '["Explain how this implementation prevents: Manual console modifications creating unresolvable drift; dangerous `-target` applications leaving state partially updat", "How does Terraform Drift Detection, Refactoring & Terragrunt scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-33', 'phase-07-lesson-33-event-streaming-fundamentals-apache-kafka', 'module-10', 33, 'Lesson 10.33: Event Streaming Fundamentals: Apache Kafka Architecture & Storage Internals', 'Prerequisites: Phase 4, Lesson 7.4', 'Prerequisites: Phase 4, Lesson 7.4 | Subtopics: 6 items', 'Systems project application', 240, 8, 1750.0, 1650.0, '# Lesson 7.33: Event Streaming Fundamentals: Apache Kafka Architecture & Storage Internals

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 4, Lesson 7.4
- **Subtopics**:
  - `7.33.1` Message queues (RabbitMQ) vs Event streaming platforms (Kafka): push vs pull, message consumption vs durable logs
  - `7.33.2` Kafka core concepts: Topics, Partitions, Brokers, Clusters, and Replication Factor
  - `7.33.3` Storage internals on disk: commit log, segments, `.log` data files, `.index` offset indexes, and `.timeindex` files
  - `7.33.4` Sequential I/O and Zero-Copy optimization: page cache utilization and `sendfile()` kernel syscall eliminating context switches
  - `7.33.5` Log retention and compaction: time-based retention, size-based retention, clean/dirty log compaction, and tombstone markers
  - `7.33.6` Kafka metadata architectures: legacy ZooKeeper coordination vs modern KRaft (Kafka Raft metadata mode)
- **Key Failure Modes & Edge Cases**: High partition counts exceeding broker memory and file descriptor limits; broker disk filling up due to uncompacted tombstone keys.
- **Verification & Mastery Check**: Deploy a multi-broker Kafka KRaft cluster; inspect partition segment files on disk with `kafka-run-class.sh kafka.tools.DumpLogSegments`.
- **Project Application**: InfraBlueprint: Distributed Kafka event streaming infrastructure.', '{"solution.py": "# Phase 7 // Lesson 7.33: Event Streaming Fundamentals: Apache Kafka Architecture & Storage Internals\n\ndef solve():\n    \"\"\"\n    Verification: Deploy a multi-broker Kafka KRaft cluster; inspect partition segment files on disk with `kafka-run-c\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.33", "subtopics_count": 6, "verification_criteria": "Deploy a multi-broker Kafka KRaft cluster; inspect partition segment files on disk with `kafka-run-class.sh kafka.tools.DumpLogSegments`.", "subtopics": ["7.33.1 Message queues (RabbitMQ) vs Event streaming platforms (Kafka): push vs pull, message consumption vs durable logs", "7.33.2 Kafka core concepts: Topics, Partitions, Brokers, Clusters, and Replication Factor", "7.33.3 Storage internals on disk: commit log, segments, `.log` data files, `.index` offset indexes, and `.timeindex` files", "7.33.4 Sequential I/O and Zero-Copy optimization: page cache utilization and `sendfile()` kernel syscall eliminating context switches", "7.33.5 Log retention and compaction: time-based retention, size-based retention, clean/dirty log compaction, and tombstone markers", "7.33.6 Kafka metadata architectures: legacy ZooKeeper coordination vs modern KRaft (Kafka Raft metadata mode)"]}'::jsonb, '["Explain how this implementation prevents: High partition counts exceeding broker memory and file descriptor limits; broker disk filling up due to uncompacted tomb", "How does Event Streaming Fundamentals: Apache Kafka Architecture & Storage Internals scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-34', 'phase-07-lesson-34-kafka-producers-consumers-guarantees-prot', 'module-10', 34, 'Lesson 10.34: Kafka Producers & Consumers: Guarantees & Protocols', 'Prerequisites: Lesson 7.33', 'Prerequisites: Lesson 7.33 | Subtopics: 6 items', 'Systems project application', 240, 8, 1810.0, 1700.0, '# Lesson 7.34: Kafka Producers & Consumers: Guarantees & Protocols

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 7.33
- **Subtopics**:
  - `7.34.1` Producer mechanics: message keys, partitioners (Murmur2 hash), batching (`batch.size`, `linger.ms`), and compression (snappy, zstd)
  - `7.34.2` Producer durability guarantees: `acks=0`, `acks=1`, and `acks=all` (`min.insync.replicas` interaction)
  - `7.34.3` Idempotent producers: sequence numbers, producer IDs (PID), and eliminating message duplication on network retry
  - `7.34.4` Consumer groups architecture: partition assignment, group coordinators, and rebalance protocols (Eager vs Incremental Cooperative)
  - `7.34.5` Offset commit semantics: at-most-once, at-least-once, and exactly-once processing (Kafka Transactions and Read-Committed)
  - `7.34.6` Handling poisoned messages: Dead Letter Queues (DLQ), non-blocking retry topics with exponential backoff delay
- **Key Failure Modes & Edge Cases**: Silent message loss caused by `acks=1` during broker crashes; consumer rebalance storms freezing stream consumption.
- **Verification & Mastery Check**: Implement a resilient Kafka consumer with non-blocking retry topics, incremental cooperative rebalancing, and dead-letter queues.
- **Project Application**: TenantIQ: Asynchronous tenant event ingestion and audit pipeline.', '{"solution.py": "# Phase 7 // Lesson 7.34: Kafka Producers & Consumers: Guarantees & Protocols\n\ndef solve():\n    \"\"\"\n    Verification: Implement a resilient Kafka consumer with non-blocking retry topics, incremental cooperative rebalan\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.34", "subtopics_count": 6, "verification_criteria": "Implement a resilient Kafka consumer with non-blocking retry topics, incremental cooperative rebalancing, and dead-letter queues.", "subtopics": ["7.34.1 Producer mechanics: message keys, partitioners (Murmur2 hash), batching (`batch.size`, `linger.ms`), and compression (snappy, zstd)", "7.34.2 Producer durability guarantees: `acks=0`, `acks=1`, and `acks=all` (`min.insync.replicas` interaction)", "7.34.3 Idempotent producers: sequence numbers, producer IDs (PID), and eliminating message duplication on network retry", "7.34.4 Consumer groups architecture: partition assignment, group coordinators, and rebalance protocols (Eager vs Incremental Cooperative)", "7.34.5 Offset commit semantics: at-most-once, at-least-once, and exactly-once processing (Kafka Transactions and Read-Committed)", "7.34.6 Handling poisoned messages: Dead Letter Queues (DLQ), non-blocking retry topics with exponential backoff delay"]}'::jsonb, '["Explain how this implementation prevents: Silent message loss caused by `acks=1` during broker crashes; consumer rebalance storms freezing stream consumption.", "How does Kafka Producers & Consumers: Guarantees & Protocols scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-35', 'phase-07-lesson-35-chaos-engineering-principles-fault-inject', 'module-10', 35, 'Lesson 10.35: Chaos Engineering: Principles, Fault Injection & LitmusChaos', 'Prerequisites: Lesson 7.1, Lesson 7.12', 'Prerequisites: Lesson 7.1, Lesson 7.12 | Subtopics: 6 items', 'Systems project application', 240, 8, 1870.0, 1750.0, '# Lesson 7.35: Chaos Engineering: Principles, Fault Injection & LitmusChaos

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 7.1, Lesson 7.12
- **Subtopics**:
  - `7.35.1` Principles of Chaos Engineering: forming steady-state hypotheses, introducing real-world events, and minimizing blast radius
  - `7.35.2` Fault injection techniques: killing pods, terminating VMs, network latency injection, packet loss, and CPU/memory pressure
  - `7.35.3` Linux network chaos with `tc` (Traffic Control) and `netem`: adding jitter, artificial delay, and packet corruption
  - `7.35.4` LitmusChaos on Kubernetes: ChaosEngine, ChaosExperiment CRDs, and automated validation probes
  - `7.35.5` Game Days: designing team chaos exercises to validate monitoring, alerts, runbooks, and self-healing systems
  - `7.35.6` Automated continuous chaos testing in CI/CD staging environments before major production releases
- **Key Failure Modes & Edge Cases**: Running un-scoped chaos experiments in production taking down core shared databases; lacking automated abort switches.
- **Verification & Mastery Check**: Execute a LitmusChaos experiment injecting 500ms network latency and 20% packet drop; verify circuit breakers trip without user errors.
- **Project Application**: InfraBlueprint: Automated chaos engineering verification harness.', '{"solution.py": "# Phase 7 // Lesson 7.35: Chaos Engineering: Principles, Fault Injection & LitmusChaos\n\ndef solve():\n    \"\"\"\n    Verification: Execute a LitmusChaos experiment injecting 500ms network latency and 20% packet drop; verify circuit\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.35", "subtopics_count": 6, "verification_criteria": "Execute a LitmusChaos experiment injecting 500ms network latency and 20% packet drop; verify circuit breakers trip without user errors.", "subtopics": ["7.35.1 Principles of Chaos Engineering: forming steady-state hypotheses, introducing real-world events, and minimizing blast radius", "7.35.2 Fault injection techniques: killing pods, terminating VMs, network latency injection, packet loss, and CPU/memory pressure", "7.35.3 Linux network chaos with `tc` (Traffic Control) and `netem`: adding jitter, artificial delay, and packet corruption", "7.35.4 LitmusChaos on Kubernetes: ChaosEngine, ChaosExperiment CRDs, and automated validation probes", "7.35.5 Game Days: designing team chaos exercises to validate monitoring, alerts, runbooks, and self-healing systems", "7.35.6 Automated continuous chaos testing in CI/CD staging environments before major production releases"]}'::jsonb, '["Explain how this implementation prevents: Running un-scoped chaos experiments in production taking down core shared databases; lacking automated abort switches.", "How does Chaos Engineering: Principles, Fault Injection & LitmusChaos scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb)
